const listTeachingsFiltered = `-- name: ListTeachingsFiltered :many
SELECT id, title, speaker, description, category, recorded_on, audio_id, duration_seconds, cover_id, published, published_at, created_by, created_at, updated_at, notified_at, category_id, edition_id, year, day_number, position, search_text, speaker_id, audio_key, audio_type, audio_size, category_slug, category_name, edition_title, edition_theme, speaker_slug
FROM teaching_details t
WHERE ($1::boolean OR t.published)
  AND ($2::bigint = 0 OR t.category_id = $2)
  AND ($3::bigint = 0 OR t.edition_id = $3)
  AND ($4::int = 0 OR t.year = $4::int)
  AND ($5::int = 0 OR t.day_number = $5::int)
  AND ($6::date IS NULL OR t.recorded_on >= $6::date)
  AND ($7::date IS NULL OR t.recorded_on <= $7::date)
  AND ($8::text = '' OR lower(public.unaccent(t.speaker)) LIKE '%' || $8::text || '%')
  AND ($9::bigint = 0 OR t.speaker_id = $9)
  AND ($10::text = '' OR NOT EXISTS (
      SELECT 1
      FROM unnest(string_to_array($10::text, ' ')) AS word
      WHERE word <> '' AND t.search_text NOT LIKE '%' || word || '%'
  ))
ORDER BY t.published DESC,
         t.year DESC NULLS LAST,
         t.day_number ASC NULLS LAST,
         t.position ASC,
         t.recorded_on DESC NULLS LAST,
         t.published_at DESC NULLS LAST,
         t.updated_at DESC,
         t.id DESC
LIMIT $12 OFFSET $11
`

type ListTeachingsFilteredParams struct {
	WithDrafts bool         `json:"with_drafts"`
	CategoryID int64        `json:"category_id"`
	EditionID  int64        `json:"edition_id"`
	Year       int32        `json:"year"`
	Day        int32        `json:"day"`
	FromDate   sql.NullTime `json:"from_date"`
	ToDate     sql.NullTime `json:"to_date"`
	Speaker    string       `json:"speaker"`
	SpeakerID  int64        `json:"speaker_id"`
	Search     string       `json:"search"`
	Off        int32        `json:"off"`
	Lim        int32        `json:"lim"`
}

// Une page d'enseignements, les publiés d'abord, les messages les plus
// récents en premier. La recherche, la catégorie, l'orateur, l'année et le
// jour sont filtrés en base: la pagination et le total restent justes.
func (q *Queries) ListTeachingsFiltered(ctx context.Context, arg ListTeachingsFilteredParams) ([]TeachingDetail, error) {
	rows, err := q.db.QueryContext(ctx, listTeachingsFiltered,
		arg.WithDrafts,
		arg.CategoryID,
		arg.EditionID,
		arg.Year,
		arg.Day,
		arg.FromDate,
		arg.ToDate,
		arg.Speaker,
		arg.SpeakerID,
		arg.Search,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TeachingDetail{}
	for rows.Next() {
		var i TeachingDetail
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Speaker,
			&i.Description,
			&i.Category,
			&i.RecordedOn,
			&i.AudioID,
			&i.DurationSeconds,
			&i.CoverID,
			&i.Published,
			&i.PublishedAt,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.NotifiedAt,
			&i.CategoryID,
			&i.EditionID,
			&i.Year,
			&i.DayNumber,
			&i.Position,
			&i.SearchText,
			&i.SpeakerID,
			&i.AudioKey,
			&i.AudioType,
			&i.AudioSize,
			&i.CategorySlug,
			&i.CategoryName,
			&i.EditionTitle,
			&i.EditionTheme,
			&i.SpeakerSlug,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const mergeTeachingSpeakers = `-- name: MergeTeachingSpeakers :exec
WITH moved AS (
    UPDATE teachings
    SET speaker_id = $2::bigint
    WHERE speaker_id = ANY($1::bigint[])
)
UPDATE teaching_speakers
SET archived_at = now(), updated_at = now()
WHERE id = ANY($1::bigint[]) AND id <> $2::bigint
`

type MergeTeachingSpeakersParams struct {
	FromIds []int64 `json:"from_ids"`
	IntoID  int64   `json:"into_id"`
}

// The teachings of the merged speakers go to [into_id]; the others are
// archived. The name of each teaching follows through its before-save trigger.
func (q *Queries) MergeTeachingSpeakers(ctx context.Context, arg MergeTeachingSpeakersParams) error {
	_, err := q.db.ExecContext(ctx, mergeTeachingSpeakers, pq.Array(arg.FromIds), arg.IntoID)
	return err
}

const replaceMediaFile = `-- name: ReplaceMediaFile :execrows
UPDATE media
SET key = $2, content_type = $3, size_bytes = $4
WHERE id = $1
`

type ReplaceMediaFileParams struct {
	ID          int64  `json:"id"`
	Key         string `json:"key"`
	ContentType string `json:"content_type"`
	SizeBytes   int64  `json:"size_bytes"`
}

// A sound re-encoded smaller: its new file, under the same media (the
// teaching that lists it doesn't change). No row once deleted meanwhile.
func (q *Queries) ReplaceMediaFile(ctx context.Context, arg ReplaceMediaFileParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, replaceMediaFile,
		arg.ID,
		arg.Key,
		arg.ContentType,
		arg.SizeBytes,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateTeaching = `-- name: UpdateTeaching :one
UPDATE teachings
SET title = $1,
    speaker = $2,
    speaker_id = $3,
    description = $4,
    category = $5,
    category_id = $6,
    edition_id = $7,
    year = $8,
    day_number = $9,
    position = $10,
    recorded_on = $11,
    audio_id = $12,
    duration_seconds = $13,
    cover_id = $14,
    published = $15,
    published_at = CASE WHEN $15::boolean THEN COALESCE(published_at, now()) ELSE published_at END,
    updated_at = now()
WHERE id = $16
RETURNING id
`

type UpdateTeachingParams struct {
	Title           string        `json:"title"`
	Speaker         string        `json:"speaker"`
	SpeakerID       sql.NullInt64 `json:"speaker_id"`
	Description     string        `json:"description"`
	Category        string        `json:"category"`
	CategoryID      sql.NullInt64 `json:"category_id"`
	EditionID       sql.NullInt64 `json:"edition_id"`
	Year            sql.NullInt16 `json:"year"`
	DayNumber       sql.NullInt16 `json:"day_number"`
	Position        int32         `json:"position"`
	RecordedOn      sql.NullTime  `json:"recorded_on"`
	AudioID         int64         `json:"audio_id"`
	DurationSeconds int32         `json:"duration_seconds"`
	CoverID         sql.NullInt64 `json:"cover_id"`
	Published       bool          `json:"published"`
	ID              int64         `json:"id"`
}

// published_at stays the date of the first publication.
func (q *Queries) UpdateTeaching(ctx context.Context, arg UpdateTeachingParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, updateTeaching,
		arg.Title,
		arg.Speaker,
		arg.SpeakerID,
		arg.Description,
		arg.Category,
		arg.CategoryID,
		arg.EditionID,
		arg.Year,
		arg.DayNumber,
		arg.Position,
		arg.RecordedOn,
		arg.AudioID,
		arg.DurationSeconds,
		arg.CoverID,
		arg.Published,
		arg.ID,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

